<?php use App\Core\Html as H; use App\Core\Money; ?>
<div class="page-heading"><div><p class="eyebrow">CADA MOVIMENTO CONTA</p><h1>Movimentações</h1><p class="text-secondary">Busque, organize e acompanhe suas receitas e despesas.</p></div><div class="d-flex gap-2 flex-wrap"><a class="btn btn-outline-secondary" href="<?= H::escape($basePath.'/movimentacoes/exportar?'.http_build_query($filters)) ?>">Exportar CSV</a><a class="btn btn-uai-primary" href="#novo">+ Novo lançamento</a></div></div>
<form method="get" class="card mb-4"><div class="card-body row g-3"><div class="col-md-6"><label class="form-label" for="activity-search">Buscar descrição</label><input id="activity-search" class="form-control" name="q" placeholder="Ex.: mercado, salário, aluguel" value="<?= H::escape($filters['q'] ?? '') ?>"></div><div class="col-md-3"><label class="form-label" for="activity-from">Competência de</label><input id="activity-from" class="form-control" type="date" name="data_inicio" value="<?= H::escape($filters['data_inicio'] ?? '') ?>"></div><div class="col-md-3"><label class="form-label" for="activity-to">Até</label><input id="activity-to" class="form-control" type="date" name="data_fim" value="<?= H::escape($filters['data_fim'] ?? '') ?>"></div>
<?php $selects=['status'=>['Situação',['pendente'=>'Pendente','efetivada'=>'Realizada','cancelada'=>'Cancelada']], 'tipo'=>['Tipo',['receita'=>'Receita','despesa'=>'Despesa']], 'conta_id'=>['Conta',array_column($accounts,'nome','id')], 'cartao_id'=>['Cartão',array_column($cards,'nome','id')], 'subgrupo_id'=>['Subcategoria',array_column(array_map(fn($c)=>['id'=>$c['id'],'nome'=>$c['grupo_nome'].' · '.$c['nome']],$categories),'nome','id')], 'meio_pagamento'=>['Meio de pagamento',['pix'=>'Pix','dinheiro'=>'Dinheiro','debito'=>'Débito','credito'=>'Crédito','boleto'=>'Boleto','transferencia'=>'Transferência','outro'=>'Outro']]]; ?>
<?php foreach($selects as $key=>[$label,$options]): ?><div class="col-md-4 col-xl-2"><label class="form-label" for="filter-<?= $key ?>"><?= $label ?></label><select id="filter-<?= $key ?>" class="form-select" name="<?= $key ?>"><option value="">Todos</option><?php foreach($options as $id=>$name): ?><option value="<?= H::escape($id) ?>" <?= (string)($filters[$key] ?? '')===(string)$id ? 'selected' : '' ?>><?= H::escape($name) ?></option><?php endforeach; ?></select></div><?php endforeach; ?><div class="col-12 d-flex gap-2"><button class="btn btn-uai-primary">Aplicar filtros</button><a class="btn btn-outline-secondary" href="<?= H::escape($basePath.'/movimentacoes') ?>">Limpar</a></div></div></form>
<section class="card mb-4"><div class="card-body"><div class="section-heading"><h2 class="h5 mb-0"><?= $total ?> <?= $total===1 ? 'lançamento' : 'lançamentos' ?></h2><span class="small text-secondary">Até 50 por página</span></div><p class="small text-secondary d-md-none">Deslize a tabela para ver valores e ações.</p><div class="table-responsive" tabindex="0" role="region" aria-label="Tabela de movimentações; role horizontalmente para ver todas as colunas"><table class="table align-middle activity-table"><thead><tr><th>Descrição / categoria</th><th>Competência</th><th>Conta / cartão</th><th>Situação</th><th class="text-end">Valor</th><th>Ações</th></tr></thead><tbody>
<?php foreach(array_slice($entries,0,50) as $t): ?><tr><td><a class="fw-semibold" href="<?= H::escape($basePath.'/movimentacoes/'.$t['id']) ?>"><?= H::escape($t['descricao']) ?></a><small class="d-block text-secondary"><?= H::escape($t['grupo_nome'].' · '.$t['subgrupo_nome']) ?> · <?= $t['recorrencia_id'] ? 'Recorrente' : ($t['parcelamento_id'] ? 'Parcela '.(int)$t['numero_parcela'].'/'.(int)$t['total_parcelas'] : 'Avulsa') ?></small></td><td><?= H::date($t['data_competencia']) ?></td><td><?= H::escape($t['cartao_nome'] ?? $t['conta_nome'] ?? 'A definir') ?></td><td><span class="badge text-bg-<?= $t['status']==='efetivada' ? 'success' : ($t['status']==='pendente' ? 'warning' : 'secondary') ?>"><?= $t['status']==='efetivada' ? 'Realizada' : H::escape(ucfirst($t['status'])) ?></span><?php if($t['estornado']): ?><small class="d-block text-secondary mt-1">Estorno: <?= Money::format((int)$t['estornado']) ?></small><?php endif; ?></td><td class="text-end text-nowrap <?= $t['tipo']==='receita' ? 'text-success' : '' ?>"><?= $t['tipo']==='receita' ? '+' : '−' ?> <?= Money::format((int)$t['valor_centavos']) ?></td><td>
<?php if($t['status']==='pendente' && !$t['cartao_id']): ?><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-secondary" href="<?= H::escape($basePath.'/movimentacoes/'.$t['id'].'/editar') ?>">Editar</a><button class="btn btn-sm btn-outline-secondary" type="button" data-bs-toggle="modal" data-bs-target="#effect-<?= (int)$t['id'] ?>">Efetivar</button><form method="post" action="<?= H::escape($basePath.'/movimentacoes/'.$t['id'].'/cancelar') ?>" data-confirm="Cancelar esta pendência?"><input type="hidden" name="_token" value="<?= H::escape($csrfToken) ?>"><button class="btn btn-sm btn-outline-danger">Cancelar</button></form></div><?php else: ?><a href="<?= H::escape($basePath.'/movimentacoes/'.$t['id']) ?>">Detalhes</a><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$entries): ?><tr><td colspan="6"><div class="empty-state"><h2 class="h5">Nenhum lançamento encontrado</h2><p>Altere os filtros ou registre seu primeiro lançamento.</p></div></td></tr><?php endif; ?></tbody></table></div><nav aria-label="Paginação" class="d-flex gap-3"><?php if($page>1): ?><a href="<?= H::escape($basePath.'/movimentacoes?'.http_build_query($filters+['pagina'=>$page-1])) ?>">← Anterior</a><?php endif; ?><span>Página <?= $page ?> de <?= max(1,(int)ceil($total/50)) ?></span><?php if(count($entries)>50): ?><a href="<?= H::escape($basePath.'/movimentacoes?'.http_build_query($filters+['pagina'=>$page+1])) ?>">Próxima →</a><?php endif; ?></nav></div></section>
<?php foreach(array_slice($entries,0,50) as $t): if($t['status']!=='pendente' || $t['cartao_id']) continue; ?>
<div class="modal fade" id="effect-<?= (int)$t['id'] ?>" tabindex="-1" aria-labelledby="effect-title-<?= (int)$t['id'] ?>" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5" id="effect-title-<?= (int)$t['id'] ?>">Efetivar <?= H::escape($t['descricao']) ?></h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Fechar"></button></div><form method="post" action="<?= H::escape($basePath.'/movimentacoes/'.$t['id'].'/efetivar') ?>"><div class="modal-body"><input type="hidden" name="_token" value="<?= H::escape($csrfToken) ?>"><label class="form-label" for="effect-account-<?= (int)$t['id'] ?>">Conta</label><select id="effect-account-<?= (int)$t['id'] ?>" name="conta_id" class="form-select mb-3" required><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)$t['conta_id']===(int)$a['id'] ? 'selected' : '' ?>><?= H::escape($a['nome']) ?></option><?php endforeach; ?></select><label class="form-label" for="effect-date-<?= (int)$t['id'] ?>">Data da efetivação</label><input id="effect-date-<?= (int)$t['id'] ?>" name="data_efetivacao" type="date" class="form-control" max="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required></div><div class="modal-footer"><button class="btn btn-uai-primary">Confirmar</button></div></form></div></div></div>
<?php endforeach; ?>
